// ─────────────────────────────────────────────────────────────────────────
//  01 · next billing date★★★
//  concepts: ZonedDateTime · plusMonths · DST
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.time.*;
import java.util.*;

class Exercise {

    /** The n-th monthly billing after start, same local time and anchor day, in the zone. */
    static Instant nthBilling(Instant start, ZoneId zone, int n) {
        if (n < 0) throw new IllegalArgumentException("n must be >= 0");
        return start.atZone(zone).plusMonths(n).toInstant();
    }

    static Instant berlin(int y, int m, int d, int hour) {
        return ZonedDateTime.of(y, m, d, hour, 0, 0, 0, ZoneId.of("Europe/Berlin")).toInstant();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a short month bills on its last day", () -> eq(nthBilling(berlin(2026, 1, 31, 9), ZoneId.of("Europe/Berlin"), 1), berlin(2026, 2, 28, 9)));
        test("the anchor day comes back after a short month", () -> eq(nthBilling(berlin(2026, 1, 31, 9), ZoneId.of("Europe/Berlin"), 2), berlin(2026, 3, 31, 9)));
        test("the local time survives the DST change", () -> eq(nthBilling(berlin(2026, 3, 15, 9), ZoneId.of("Europe/Berlin"), 1), Instant.parse("2026-04-15T07:00:00Z")));
        test("leap years give February 29", () -> eq(nthBilling(berlin(2028, 1, 30, 9), ZoneId.of("Europe/Berlin"), 1), berlin(2028, 2, 29, 9)));
        test("n = 0 is the start; negative n is rejected (boundary)", () -> { var s = Instant.parse("2026-05-05T10:00:00Z"); eq(nthBilling(s, ZoneId.of("UTC"), 0), s); raises(IllegalArgumentException.class, () -> nthBilling(s, ZoneId.of("UTC"), -1)); });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

fund-java/13-java-time/01-next-billing-d.explanation:
Compute every billing from the START (not from the previous bill) so the anchor day survives short months:

```java
if (n < 0) throw new IllegalArgumentException("n must be >= 0");
ZonedDateTime first = start.atZone(zone);
return first.plusMonths(n).toInstant();
```

`plusMonths` clamps to the month's last day and keeps the local time, applying the zone's offset for THAT date, so DST is handled. Chaining from the previous bill (Jan 31 → Feb 28 → Mar 28) would lose the 31st forever, and adding Durations to the Instant would drift by an hour across DST.
